// Parse comma-separated phone numbers and store for SMS interface (514)
const raw = (msg.payload != null ? String(msg.payload) : '').trim();
const list = raw
    .split(',')
    .map(s => s.trim())
    .filter(s => s.length > 0);
flow.set('sms_allowed_phones', list);
if (list.length > 0) {
    node.status({ fill: 'green', shape: 'dot', text: list.length + ' allowed' });
} else {
    node.status({ fill: 'grey', shape: 'ring', text: 'allow all' });
}
return null;

// Set default allowed numbers at flow start (SMS command interface 514)
// Use full numbers with country code to match gateway 'from' (e.g. 40740244845)
flow.set('sms_allowed_phones', ['+40740244845', '+40745218721']);
node.status({ fill: 'green', shape: 'dot', text: '2 allowed' });
return null;

// Get phone and message from flow context (set by text inputs)
let phone = flow.get('sms_phone') || '';
const message = flow.get('sms_message') || '';

if (!phone || !message) {
    node.warn('Phone number or message missing');
    return null;
}

// Strip all non-digits for MQTT (gateway expects digits-only in 'to')
phone = String(phone).replace(/\D/g, '');

// Create SMS command payload (JSON string for gateway)
msg.payload = JSON.stringify({ to: phone, text: message });
msg.topic = 'sms/gateway/command/send';

// Store timestamp for tracking
msg.timestamp = new Date().toISOString();

return msg;

// Store phone and message in flow context when text inputs change
if (msg.topic === 'phone') {
    flow.set('sms_phone', msg.payload);
} else if (msg.topic === 'message') {
    flow.set('sms_message', msg.payload);
}
return null;

let metadataKey = "status_metadata_sms_gateway";
let metadata = flow.get(metadataKey) || {
    lastReportedMs: null,
    lastChangedMs: null,
    previousState: "Unknown",
    currentState: "Unknown"
};

// Parse status - could be timestamp string, JSON, or 'offline' trigger
let statusData = msg.payload;
let newState = "online";

if (statusData === "offline") {
    newState = "offline";
} else if (typeof statusData === 'string') {
    // Try to parse as JSON
    try {
        statusData = JSON.parse(statusData);
        newState = statusData.wifi === 'connected' && statusData.mqtt === 'connected' ? 'online' : 'offline';
    } catch (e) {
        // It's a timestamp string or other reported data, device is online
        newState = 'online';
    }
} else if (typeof statusData === 'object') {
    newState = statusData.wifi === 'connected' && statusData.mqtt === 'connected' ? 'online' : 'offline';
}

let nowMs = Date.now();

// Only update lastReported if it's an actual report, not a heartbeat timeout
if (statusData !== "offline") {
    metadata.lastReportedMs = nowMs;
}

if (newState !== metadata.currentState) {
    metadata.previousState = metadata.currentState;
    metadata.currentState = newState;
    metadata.lastChangedMs = nowMs;
}

flow.set(metadataKey, metadata);
msg.metadata = metadata;
msg.payload = typeof statusData === 'object' ? statusData : { timestamp: statusData, wifi: 'connected', mqtt: 'connected', gsm: 'initialized' };
flow.set('sms_gateway_status', msg.payload);

return msg;

// Format response for UI notification
const response = msg.payload;
const success = response.success || false;
const phone = response.to || 'Unknown';
const timestamp = response.timestamp || new Date().toISOString();

const emoji = success ? '✅' : '❌';
const status = success ? 'Success' : 'Failed';

msg.payload = {
    success: success,
    phone: phone,
    timestamp: timestamp,
    message: `${emoji} SMS ${status} to ${phone}`
};

return msg;

